const getPlaceCoordinates = (placeName: string, savedLat?: string | number | null, savedLng?: string | number | null): { lat: number; lng: number } => {
  // أولاً: استخدم الإحداثيات المحفوظة في قاعدة البيانات إذا كانت موجودة
