      });
      setShowAddForm(prev => ({ ...prev, [variables.sectionKey]: false }));
      setNewCardData(prev => ({ ...prev, [variables.sectionKey]: { titleAr: '', titleEn: '', contentAr: '', contentEn: '', imageUrl: '', buttonLink: '', buttonText: '', buttonTextEn: '', position: 'grid' } }));
