            onClick={() => setIsEditing(!isEditing)}
            data-testid="button-edit-contact-info"
          >
            <Edit className="w-4 h-4 ml-2" />
            {isEditing ? (language === 'ar' ? 'إلغاء' : 'Cancel') : (language === 'ar' ? 'تعديل' : 'Edit')}
